#pragma once

// Glyph names (ISO 32000-2 §9.6.5): the Adobe Glyph List, which gives a name its Unicode value, and the
// standard Latin encodings of Annex D as the glyph names of their codes. The tables are generated by
// scripts/gen_glyph_tables.py (glyph_tables.cpp); the lookups over them are in glyph_names.cpp.

#include <cstdint>
#include <optional>
#include <span>
#include <string_view>

namespace capriole::font::detail {

enum class BaseEncoding : std::uint8_t { kStandard, kWinAnsi, kMacRoman };

struct GlyphUnicode {
  std::string_view name;
  char32_t unicode;
};

// The AGL (with the ZapfDingbats names a1, a2, ...), sorted by name.
[[nodiscard]] std::span<const GlyphUnicode> glyph_list();

// The glyph name of each code of an encoding; empty for the codes it leaves undefined.
[[nodiscard]] std::span<const std::string_view, 256> encoding_table(BaseEncoding encoding);

// The Unicode value of a glyph name: the AGL, then uniXXXX and uXXXX[XX] (§9.10.2 and the AGL
// specification). A suffix after a period (a.sc, one.oldstyle) is dropped first.
[[nodiscard]] std::optional<char32_t> glyph_unicode(std::string_view name);

// The code of a glyph name in an encoding, when it has one (the lowest, for names that occur twice).
[[nodiscard]] std::optional<std::uint8_t> encoding_code(BaseEncoding encoding, std::string_view name);

}  // namespace capriole::font::detail
